[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "temp-converter-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "temp-converter-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "summary_card"
              },
              {
                "id": "details_card"
              },
              {
                "id": "results_card"
              }
            ]
          }
        },
        {
          "id": "summary_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "summary_text"
            }
          }
        },
        {
          "id": "summary_text",
          "type": "Text",
          "properties": {
            "text": "A temperature of **98.6°F** is equivalent to **37°C** and **310.15 K**.",
            "style": "body"
          }
        },
        {
          "id": "details_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "details_column"
            }
          }
        },
        {
          "id": "details_column",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "details_title"
              },
              {
                "id": "conversion_tabs"
              }
            ]
          }
        },
        {
          "id": "details_title",
          "type": "Text",
          "properties": {
            "text": "Step-by-step Conversion",
            "style": "title"
          }
        },
        {
          "id": "conversion_tabs",
          "type": "Tabs",
          "properties": {
            "tabs": [
              {
                "label": "Fahrenheit to Celsius",
                "child": {
                  "id": "f_to_c_column"
                }
              },
              {
                "label": "Celsius to Kelvin",
                "child": {
                  "id": "c_to_k_column"
                }
              }
            ]
          }
        },
        {
          "id": "f_to_c_column",
          "type": "Column",
          "properties": {
            "spacing": "small",
            "children": [
              {
                "id": "f_to_c_formula_title"
              },
              {
                "id": "f_to_c_formula_text"
              },
              {
                "id": "f_to_c_calc_title"
              },
              {
                "id": "f_to_c_calc_text"
              },
              {
                "id": "f_to_c_divider"
              },
              {
                "id": "f_to_c_result_text"
              }
            ]
          }
        },
        {
          "id": "f_to_c_formula_title",
          "type": "Text",
          "properties": {
            "text": "Formula",
            "style": "subheading"
          }
        },
        {
          "id": "f_to_c_formula_text",
          "type": "Text",
          "properties": {
            "text": "C = (F - 32) * 5/9",
            "style": "code"
          }
        },
        {
          "id": "f_to_c_calc_title",
          "type": "Text",
          "properties": {
            "text": "Calculation",
            "style": "subheading"
          }
        },
        {
          "id": "f_to_c_calc_text",
          "type": "Text",
          "properties": {
            "text": "C = (98.6 - 32) * 5/9\nC = (66.6) * 5/9\nC = 333 / 9",
            "style": "code"
          }
        },
        {
          "id": "f_to_c_divider",
          "type": "Divider"
        },
        {
          "id": "f_to_c_result_text",
          "type": "Text",
          "properties": {
            "text": "**Result: 37° Celsius**",
            "style": "body"
          }
        },
        {
          "id": "c_to_k_column",
          "type": "Column",
          "properties": {
            "spacing": "small",
            "children": [
              {
                "id": "c_to_k_formula_title"
              },
              {
                "id": "c_to_k_formula_text"
              },
              {
                "id": "c_to_k_calc_title"
              },
              {
                "id": "c_to_k_calc_text"
              },
              {
                "id": "c_to_k_divider"
              },
              {
                "id": "c_to_k_result_text"
              }
            ]
          }
        },
        {
          "id": "c_to_k_formula_title",
          "type": "Text",
          "properties": {
            "text": "Formula",
            "style": "subheading"
          }
        },
        {
          "id": "c_to_k_formula_text",
          "type": "Text",
          "properties": {
            "text": "K = C + 273.15",
            "style": "code"
          }
        },
        {
          "id": "c_to_k_calc_title",
          "type": "Text",
          "properties": {
            "text": "Calculation",
            "style": "subheading"
          }
        },
        {
          "id": "c_to_k_calc_text",
          "type": "Text",
          "properties": {
            "text": "K = 37 + 273.15",
            "style": "code"
          }
        },
        {
          "id": "c_to_k_divider",
          "type": "Divider"
        },
        {
          "id": "c_to_k_result_text",
          "type": "Text",
          "properties": {
            "text": "**Result: 310.15 Kelvin**",
            "style": "body"
          }
        },
        {
          "id": "results_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "results_column"
            }
          }
        },
        {
          "id": "results_column",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "results_title"
              },
              {
                "id": "results_table"
              }
            ]
          }
        },
        {
          "id": "results_title",
          "type": "Text",
          "properties": {
            "text": "Conversion Results",
            "style": "title"
          }
        },
        {
          "id": "results_table",
          "type": "Table",
          "properties": {
            "columns": [
              {
                "header": "Fahrenheit"
              },
              {
                "header": "Celsius"
              },
              {
                "header": "Kelvin"
              }
            ],
            "rows": [
              [
                "98.6",
                "37.0",
                "310.15"
              ]
            ]
          }
        }
      ]
    }
  }
]
